@import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* HUD Sci-Fi — cool dark blue, thin cyan lines, corner brackets, radar data */
.theme-hud-scifi {
  --bg: oklch(0.170 0.017 252.7);
  --surface: oklch(0.201 0.024 251.6);
  --surface-2: oklch(0.239 0.032 252.9);
  --fg: oklch(0.922 0.025 240.7);
  --fg-muted: oklch(0.620 0.050 244.7);
  --accent: oklch(0.806 0.129 212.2);
  --accent-fg: oklch(0.173 0.027 233.6);
  --accent-2: oklch(0.623 0.200 265.8);
  --line: oklch(0.75 0.1 220 / 30%);
  --success: oklch(0.845 0.198 153.3);
  --warning: oklch(0.839 0.152 90.4);
  --danger: oklch(0.650 0.199 29.8);
  --radius: 2px;
  --radius-sm: 1px;
  --radius-lg: 3px;
  --radius-pill: 3px;
  --shadow-1: 0 0 12px oklch(0.75 0.12 220 / 15%);
  --shadow-2: 0 0 24px oklch(0.75 0.12 220 / 20%);
  --shadow-3: 0 0 48px oklch(0.75 0.12 220 / 25%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 50%, transparent), 0 0 16px color-mix(in oklab, var(--accent) 30%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Rajdhani", sans-serif;
  --font-body: "Rajdhani", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.06em;
  --label-transform: uppercase;
  --label-tracking: 0.22em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-hud-scifi h1,
.theme-hud-scifi h2,
.theme-hud-scifi h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}
.theme-hud-scifi h1, .theme-hud-scifi h2, .theme-hud-scifi h3 { text-transform: uppercase; }

/* signature */
.theme-hud-scifi { --font-ui: var(--font-display); background-image: repeating-linear-gradient(0deg, transparent 0 3px, oklch(0.75 0.1 220 / 4%) 3px 4px); }
.theme-hud-scifi h1, .theme-hud-scifi h2 { text-shadow: 0 0 12px color-mix(in oklab, var(--accent) 60%, transparent); }
.theme-hud-scifi button { clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px); text-transform: uppercase; letter-spacing: 0.14em; }

/* depth */
.theme-hud-scifi thead th { font-family: var(--font-mono); font-size: 0.66rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.2em; color: var(--accent); background: transparent; border-bottom: 1px solid color-mix(in oklab, var(--accent) 40%, transparent); }
.theme-hud-scifi td { border-bottom: 1px solid oklch(0.75 0.1 220 / 12%); font-variant-numeric: tabular-nums; }
.theme-hud-scifi tbody tr { transition: background-color 0.1s linear, box-shadow 0.1s linear; }
.theme-hud-scifi tbody tr:hover { background: color-mix(in oklab, var(--accent) 7%, transparent); box-shadow: inset 2px 0 0 var(--accent); }
.theme-hud-scifi input, .theme-hud-scifi select, .theme-hud-scifi textarea { background: oklch(0.14 0.015 252 / 80%); border: 1px solid var(--line); border-radius: var(--radius-sm); caret-color: var(--accent); font-family: var(--font-mono); }
.theme-hud-scifi input:focus-visible, .theme-hud-scifi select:focus-visible, .theme-hud-scifi textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-hud-scifi kbd { font-family: var(--font-mono); font-size: 0.7em; padding: 0.1em 0.45em; color: var(--accent); background: transparent; border: 1px solid color-mix(in oklab, var(--accent) 50%, transparent); border-radius: var(--radius-sm); }
.theme-hud-scifi a { color: var(--accent); text-decoration: none; border-bottom: 1px solid color-mix(in oklab, var(--accent) 40%, transparent); }
.theme-hud-scifi a:hover { border-bottom-color: var(--accent); text-shadow: 0 0 10px color-mix(in oklab, var(--accent) 70%, transparent); }
.theme-hud-scifi ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
.theme-hud-scifi ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-hud-scifi ::-webkit-scrollbar-track { background: transparent; }
.theme-hud-scifi ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--accent) 40%, transparent); border-radius: 1px; }
.theme-hud-scifi ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-hud-scifi .label-caps { font-family: var(--font-mono); color: var(--fg-muted); }
.theme-hud-scifi .label-caps::before { content: "▸ "; color: var(--accent); }
/* targeting brackets: four painted corners on framed panels */
.theme-hud-scifi .themed-border { border-color: var(--line); background-image: linear-gradient(var(--accent), var(--accent)), linear-gradient(var(--accent), var(--accent)), linear-gradient(var(--accent), var(--accent)), linear-gradient(var(--accent), var(--accent)), linear-gradient(var(--accent), var(--accent)), linear-gradient(var(--accent), var(--accent)), linear-gradient(var(--accent), var(--accent)), linear-gradient(var(--accent), var(--accent)); background-repeat: no-repeat; background-position: top left, top left, top right, top right, bottom left, bottom left, bottom right, bottom right; background-size: 12px 1px, 1px 12px, 12px 1px, 1px 12px, 12px 1px, 1px 12px, 12px 1px, 1px 12px; }
.theme-hud-scifi button:active { box-shadow: inset 0 0 12px color-mix(in oklab, var(--accent) 30%, transparent); }

/* alt mode: daylight ops — white console, ink-cyan telemetry */
.theme-hud-scifi.alt-mode {
  --bg: oklch(0.98 0.012 252.7);
  --surface: oklch(0.955 0.015 252.7);
  --surface-2: oklch(0.92 0.017 252.7);
  --fg: oklch(0.2 0.02 252);
  --fg-muted: oklch(0.45 0.04 245);
  --line: oklch(0.52 0.1 212 / 30%);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --accent: oklch(0.52 0.129 212.2);
  --accent-2: oklch(0.5 0.2 265.8);
  --accent-fg: oklch(1 0 0);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 50%, transparent), 0 0 12px color-mix(in oklab, var(--accent) 20%, transparent);
  background-image: repeating-linear-gradient(0deg, transparent 0 3px, oklch(0.52 0.1 212 / 3%) 3px 4px);
}
.theme-hud-scifi.alt-mode h1, .theme-hud-scifi.alt-mode h2 { text-shadow: none; }
.theme-hud-scifi.alt-mode td { border-bottom-color: oklch(0.52 0.1 212 / 18%); }
.theme-hud-scifi.alt-mode input, .theme-hud-scifi.alt-mode select, .theme-hud-scifi.alt-mode textarea { background: oklch(1 0 0 / 75%); }
.theme-hud-scifi.alt-mode ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--accent) 55%, transparent); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
